const getIcon = (iconName?: string): LucideIcon | typeof FiduciaryIcon => {
    if (!iconName) return Circle
    if (iconName.startsWith('lucide-')) return lucideIconMap[iconName.slice(7)] || Circle
    return legacyIconMap[iconName] || Circle
}

// ── i18n: use Frappe's __ when present, else identity. `context` picks the entry kept for that place
// (msgctxt), so a generic word - « On », « Off » - is translated for this place without deciding that
// word for the whole desk; Frappe falls back to the bare entry when the context has none.
const tr = (text: string, args?: (string | number)[], context?: string): string => {
    const w = window as unknown as { __?: (t: string, a?: (string | number)[], c?: string) => string }
    let s = typeof w.__ === 'function' ? w.__(text, args, context) : text
    if (args && s === text) s = text.replace(/\{(\d+)\}/g, (_, i) => String(args[+i] ?? ''))
    return s
}

// ── touch mode: owned by neoffice_theme, which ships on its own schedule.
// This bundle is vendored into frappe and reaches an instance with the desk,
// so it WILL run beside a theme older than itself. Feature-detecting the
// object is not enough -- `decided` was added after `on`/`off`/`auto`, and
// calling it on the older object throws at mount and takes the whole cockpit
// down. Every member this file uses is checked, once, here.
const touchApi = (): NonNullable<FrappeWin['neoffice_touch']> | null => {
    const t = (window as unknown as FrappeWin).neoffice_touch
    if (!t) return null
    const complet = (['on', 'off', 'auto', 'active', 'decided'] as const).every(k => typeof t[k] === 'function')
    return complet ? t : null
}

interface WorkspacePage { name: string; title: string; label?: string; icon?: string; public?: boolean | number; app?: string; parent_page?: string; module?: string }
interface AppData { app_name: string; app_title: string; app_logo_url?: string; app_route?: string; workspaces: string[]; modules?: string[] }
//// Neoffice — a space of Simple mode's sidebar (neoffice_theme boot_override.simple_spaces, 03.10).
interface SimpleSpace { space: string; app: string; label: string; icon?: string; tab?: string; route: string }
//// Neoffice — the number beside a space's sidebar entry, by entry name (neoffice_theme workspace_tabs.space_counts).
type SpaceCounts = Record<string, { count: number; tone?: string }>
//// Neoffice — a space's tabs as the sidebar's entries (neoffice_theme workspace_tabs.js publishNav).
interface SpaceNavItem { key: string; label: string; icon?: string; count?: number; tone?: string; active?: boolean }
interface SpaceNav { space: string; app: string | null; label: string; items: SpaceNavItem[] }
interface UserInfoEntry { fullname?: string; image?: string; abbr?: string; email?: string }

interface FrappeWin {
    /** Opens the phone-pairing dialog. Defined by neoffice_theme,
     *  loaded across the whole desk (`app_include_js`) — so always present in
     *  the `desk` env, and never anywhere else. */
    showMobileAppsDialog?: () => void
    /** Touch mode, also defined by neoffice_theme and therefore `desk` only.
     *  Three states because the model has three: `auto` follows the pointer and
     *  the role, `on` and `off` are a decision taken ON THIS DEVICE -- a touch
     *  screen belongs to the machine, not to the person, and the same account
     *  is used on the workshop PC and on a laptop. */
    neoffice_touch?: { on: () => void; off: () => void; auto: () => void; active: () => boolean; decided: () => boolean }
    frappe?: {
        boot?: {
            sidebar_pages?: { pages?: WorkspacePage[] }
            app_data?: AppData[]
            /** Desk pages the user may open. `module` is a Neoffice addition to
             *  frappe/boot.py — upstream sends title + modified only. */
            page_info?: Record<string, { title?: string; module?: string }>
            neoffice_settings?: { interface_mode?: string }
            user?: { name?: string; email?: string; full_name?: string; user_image?: string; view_interface?: string }
            user_info?: Record<string, UserInfoEntry>
            app_logo_url?: string
        }
        set_route?: (...parts: string[]) => void
        /** The parsed desk route: ['List', 'Gym Program'] / ['Form', 'Gym Program', name] / ['gym-coach-board']. */
        get_route?: () => string[]
        /** A doctype's meta, present once its list or form has loaded it. */
        get_meta?: (doctype: string) => { module?: string } | null | undefined
        /** Loads a doctype's meta; resolves when `get_meta` will answer. */
        model?: { with_doctype?: (doctype: string) => Promise<unknown> | unknown }
        session?: { user?: string }
        ui?: { NeofficeCalculatorDialog?: { show: () => void } }
        db?: { get_list?: (doctype: string, opts?: { fields?: string[]; limit?: number }) => Promise<Array<{ name: string }>> }
    }
    __FRAPPE_INTEGRATION__?: boolean
    csrf_token?: string
}

