/**
 * SPA companion panels — notifications · synk (Raven) · help.
 *
 * On the desk these features are provided by desk-only modules (native
 * frappe.ui.Notifications, the docked Raven widget, nora's help panel).
 * SPA surfaces (Mint / Raven / Neoconstruction — and tomorrow Drive, LMS,
 * Helpdesk, CRM) don't load any of that, so NeoCockpit ships LIGHT panels
 * that talk to the same whitelisted APIs directly (same origin, session
 * cookies — no extra runtime). One implementation here = every surface
 * that mounts NeoCockpit gets the full rail for free.
 *
 * v1 scope: read-only lists + deep links (no realtime in SPAs — badges
 * poll every 60s and refresh when a panel opens).
 */
import { useState, useEffect, useCallback, useRef } from 'react'
import { ExternalLink, Search, SquarePen, CalendarDays, CalendarClock, AlarmClock } from 'lucide-react'
import { cn } from './utils'
// //// Neoffice — « Demander de l'aide » in the help panel (src/assistLoader.ts) ////
import { loadAssist } from './assistLoader'

const POLL_MS = 60_000

async function api<T>(method: string, params?: Record<string, string>): Promise<T | null> {
    try {
        const qs = params ? '?' + new URLSearchParams(params).toString() : ''
        const r = await fetch(`/api/method/${method}${qs}`, {
            headers: { 'X-Frappe-Site-Name': window.location.hostname },
            credentials: 'include',
        })
        if (!r.ok) return null
        return ((await r.json()) || {}).message ?? null
    } catch {
        return null
    }
}

export async function apiPost<T>(method: string, args?: Record<string, unknown>): Promise<T | null> {
    try {
        const w = window as unknown as { csrf_token?: string; frappe?: { csrf_token?: string } }
        const r = await fetch(`/api/method/${method}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Frappe-Site-Name': window.location.hostname,
                'X-Frappe-CSRF-Token': w.csrf_token || w.frappe?.csrf_token || '',
            },
            credentials: 'include',
            body: JSON.stringify(args || {}),
        })
        if (!r.ok) return null
        return ((await r.json()) || {}).message ?? null
    } catch {
        return null
    }
}

const fmtTime = (ts?: string) => {
    if (!ts) return ''
    const d = new Date(ts.replace(' ', 'T'))
    if (isNaN(d.getTime())) return ''
    const today = new Date()
    return d.toDateString() === today.toDateString()
        ? d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        : d.toLocaleDateString([], { day: 'numeric', month: 'short' })
}

// ── notifications ───────────────────────────────────────────────────
interface NotificationLog {
    name: string
    subject?: string
    document_type?: string
    document_name?: string
    from_user?: string
    read?: 0 | 1
    creation?: string
}

export function useUnreadNotifications(enabled: boolean) {
    const [count, setCount] = useState(0)
    useEffect(() => {
        if (!enabled) return
        const load = async () => {
            const res = await api<{ notification_logs?: NotificationLog[] }>(
                'frappe.desk.doctype.notification_log.notification_log.get_notification_logs',
                { limit: '20' }
            )
            setCount((res?.notification_logs || []).filter(l => !l.read).length)
        }
        load()
        const id = setInterval(load, POLL_MS)
        return () => clearInterval(id)
    }, [enabled])
    return count
}

export function NotificationsPanel({ tr, onClose }: { tr: (s: string) => string; onClose: () => void }) {
    const [logs, setLogs] = useState<NotificationLog[] | null>(null)
    useEffect(() => {
        api<{ notification_logs?: NotificationLog[] }>(
            'frappe.desk.doctype.notification_log.notification_log.get_notification_logs',
            { limit: '20' }
        ).then(res => setLogs(res?.notification_logs || []))
    }, [])
    return (
        <div className="nc-spa-panel">
            <div className="head">
                <span className="t">{tr('Notifications')}</span>
                <a className="open" href="/app/notification-log" title={tr('Open notifications')}><ExternalLink size={14} /></a>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {logs === null && <div className="empty">…</div>}
                {logs !== null && !logs.length && <div className="empty">{tr('No notifications')}</div>}
                {(logs || []).map(l => (
                    <a key={l.name}
                        className={cn('row', !l.read && 'unread')}
                        href={l.document_type && l.document_name
                            ? `/app/${l.document_type.toLowerCase().replace(/ /g, '-')}/${encodeURIComponent(l.document_name)}`
                            : '/app/notification-log'}>
                        <span className="dot" />
                        <span className="main">
                            {/* subject is server-rendered trusted HTML (same as the desk panel) */}
                            <span className="s" dangerouslySetInnerHTML={{ __html: l.subject || '' }} />
                            <span className="m">{fmtTime(l.creation)}</span>
                        </span>
                    </a>
                ))}
            </div>
        </div>
    )
}

// ── synk (Raven) ────────────────────────────────────────────────────
interface RavenChannel {
    name: string
    channel_name?: string
    is_direct_message?: 0 | 1
    peer_user_id?: string
    last_message_details?: { content?: string; owner?: string } | string
    last_message_timestamp?: string
}

export function useUnreadSynk(enabled: boolean) {
    const [count, setCount] = useState(0)
    useEffect(() => {
        if (!enabled) return
        const load = async () => {
            const res = await api<{ name: string; unread_count: number }[]>(
                'raven.api.raven_message.get_unread_count_for_channels'
            )
            setCount((res || []).reduce((a, c) => a + (c.unread_count || 0), 0))
        }
        load()
        const id = setInterval(load, POLL_MS)
        return () => clearInterval(id)
    }, [enabled])
    return count
}

export function SynkPanel({ tr, userInfo, onClose }: {
    tr: (s: string) => string
    userInfo: Record<string, { fullname?: string }>
    onClose: () => void
}) {
    const [channels, setChannels] = useState<RavenChannel[] | null>(null)
    const [dms, setDms] = useState<RavenChannel[]>([])
    const [unread, setUnread] = useState<Record<string, number>>({})
    useEffect(() => {
        api<{ channels?: RavenChannel[]; dm_channels?: RavenChannel[] }>(
            'raven.api.raven_channel.get_all_channels', { hide_archived: '1' }
        ).then(res => {
            setChannels(res?.channels || [])
            setDms(res?.dm_channels || [])
        })
        api<{ name: string; unread_count: number }[]>(
            'raven.api.raven_message.get_unread_count_for_channels'
        ).then(res => {
            const map: Record<string, number> = {}
            for (const c of res || []) map[c.name] = c.unread_count
            setUnread(map)
        })
    }, [])
    const last = (c: RavenChannel) => {
        const d = c.last_message_details
        if (!d) return ''
        try {
            const o = typeof d === 'string' ? JSON.parse(d) : d
            return String(o.content || '').replace(/<[^>]+>/g, '').slice(0, 60)
        } catch { return '' }
    }
    const row = (c: RavenChannel, label: string, avatar: React.ReactNode) => (
        <a key={c.name} className="row" href={`/raven/channel/${encodeURIComponent(c.name)}`}>
            {avatar}
            <span className="main">
                <span className="s">{label}</span>
                {last(c) && <span className="m">{last(c)}</span>}
            </span>
            {unread[c.name] ? <span className="badge">{unread[c.name]}</span> : null}
        </a>
    )
    return (
        <div className="nc-spa-panel">
            <div className="head">
                <span className="t" style={{ fontFamily: '"Cal Sans", inherit' }}>synk</span>
                <a className="open" href="/raven" title={tr('Open Synk')}><ExternalLink size={14} /></a>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {channels === null && <div className="empty">…</div>}
                {channels !== null && (
                    <>
                        {channels.length > 0 && <div className="sect">{tr('Channels')}</div>}
                        {channels.map(c => row(c, c.channel_name || c.name,
                            <span className="av sq">#</span>))}
                        {dms.length > 0 && <div className="sect">{tr('Direct messages')}</div>}
                        {dms.map(c => {
                            const peer = c.peer_user_id || ''
                            // mini-boots may lack user_info — prettify the email local part
                            const pretty = peer.split('@')[0].replace(/[._-]+/g, ' ')
                                .replace(/\b\w/g, ch => ch.toUpperCase())
                            const name = userInfo[peer]?.fullname || pretty || c.channel_name || ''
                            return row(c, name,
                                <span className="av">{(name[0] || '?').toUpperCase()}</span>)
                        })}
                        {!channels.length && !dms.length && <div className="empty">{tr('No conversations')}</div>}
                    </>
                )}
            </div>
        </div>
    )
}

// ── mail (synk + webmail behind one envelope) ───────────────────────
interface WebmailAccount { name: string; email_address?: string; email?: string }
interface WebmailEmail {
    uid: number
    subject?: string
    from_name?: string
    from_email?: string
    date?: string
    seen?: boolean
}

/** Envelope click → tiny chooser: team chat (synk) or inbox (webmail).
 *  Webmail entry adapts: hidden when the app is absent, CTA when no
 *  account is configured. */
export function MailMenu({ tr, onSynk, onMail, onConfigure, onClose }: {
    tr: (s: string) => string
    onSynk: (() => void) | null
    onMail: () => void
    onConfigure: () => void
    onClose: () => void
}) {
    // 'loading' → probe; 'ready' (accounts) | 'none' (no account) | 'absent' (app missing)
    const [mailState, setMailState] = useState<'loading' | 'ready' | 'none' | 'absent'>('loading')
    const [synkCount, setSynkCount] = useState(0)
    const [mailCount, setMailCount] = useState(0)
    // SMS is offered only where the instance can send AND the user is allowed:
    // one phone and one monthly quota are shared by everyone.
    const [smsReady, setSmsReady] = useState(false)
    useEffect(() => {
        if (onSynk) {
            api<{ name: string; unread_count: number }[]>(
                'raven.api.raven_message.get_unread_count_for_channels'
            ).then(res => setSynkCount((res || []).reduce((a, c) => a + (c.unread_count || 0), 0)))
        }
        api<{ enabled: boolean; allowed: boolean }>('neoffice_theme.sms.can_use_sms')
            .then(res => setSmsReady(!!(res && res.enabled && res.allowed)))
            .catch(() => setSmsReady(false))
        api<WebmailAccount[]>('frappe_webmail.webmail_api.get_accounts').then(accounts => {
            if (accounts === null) { setMailState('absent'); return }
            if (!accounts.length) { setMailState('none'); return }
            setMailState('ready')
            api<{ emails?: WebmailEmail[] }>('frappe_webmail.webmail_api.get_emails', {
                account_name: accounts[0].name, folder: 'INBOX', limit: '20',
            }).then(res => setMailCount((res?.emails || []).filter(e => !e.seen).length))
        })
    }, [onSynk])
    return (
        <div className="nc-spa-panel nc-mini">
            <div className="head">
                <span className="t">{tr('Messages')}</span>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {onSynk && (
                    <button className="row" onClick={onSynk}>
                        <span className="av sq">#</span>
                        <span className="main">
                            <span className="s" style={{ fontFamily: '"Cal Sans", inherit' }}>synk</span>
                            <span className="m">{tr('Team messaging')}</span>
                        </span>
                        {synkCount > 0 && <span className="badge">{synkCount}</span>}
                    </button>
                )}
                {mailState === 'ready' && (
                    <button className="row" onClick={onMail}>
                        <span className="av">@</span>
                        <span className="main">
                            <span className="s">{tr('Email')}</span>
                            <span className="m">{tr('Inbox')}</span>
                        </span>
                        {mailCount > 0 && <span className="badge">{mailCount}</span>}
                    </button>
                )}
                {smsReady && (
                    <button className="row" onClick={() => {
                        onClose()
                        const w = window as unknown as { neoffice?: { sms?: { quick_send?: () => void } } }
                        w.neoffice?.sms?.quick_send?.()
                    }}>
                        <span className="av">✉</span>
                        <span className="main">
                            <span className="s">{tr('SMS')}</span>
                            <span className="m">{tr('Send a text message')}</span>
                        </span>
                    </button>
                )}
                {mailState === 'none' && (
                    <button className="row" onClick={onConfigure}>
                        <span className="av">@</span>
                        <span className="main">
                            <span className="s">{tr('Email')}</span>
                            <span className="m">{tr('Set up an email address')}</span>
                        </span>
                    </button>
                )}
            </div>
        </div>
    )
}

export function MailPanel({ tr, onOpenWebmail, onClose }: {
    tr: (s: string) => string
    // optional query suffix ("?compose=1" / "?account=…&folder=…&uid=…") —
    // consumed once by the webmail page's deep-link support (applyUrlIntent)
    onOpenWebmail: (query?: string) => void
    onClose: () => void
}) {
    const [state, setState] = useState<'loading' | 'ready' | 'none'>('loading')
    const [emails, setEmails] = useState<WebmailEmail[]>([])
    const [account, setAccount] = useState('')
    useEffect(() => {
        api<WebmailAccount[]>('frappe_webmail.webmail_api.get_accounts').then(accounts => {
            if (!accounts || !accounts.length) { setState('none'); return }
            setAccount(accounts[0].name)
            api<{ emails?: WebmailEmail[] }>('frappe_webmail.webmail_api.get_emails', {
                account_name: accounts[0].name, folder: 'INBOX', limit: '10',
            }).then(res => {
                setEmails(res?.emails || [])
                setState('ready')
            })
        })
    }, [])
    return (
        <div className="nc-spa-panel">
            <div className="head">
                <span className="t">{tr('Email')}</span>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {state === 'loading' && <div className="empty">…</div>}
                {state === 'none' && (
                    <div className="empty">
                        <p style={{ margin: '6px 0 14px' }}>{tr('No email account configured yet.')}</p>
                        <button className="cta" onClick={() => onOpenWebmail()}>{tr('Set up an email address')}</button>
                    </div>
                )}
                {state === 'ready' && !emails.length && <div className="empty">{tr('Inbox is empty')}</div>}
                {state === 'ready' && emails.map(e => {
                    const who = e.from_name || e.from_email || '?'
                    return (
                        <button key={e.uid} className={cn('row', !e.seen && 'unread')}
                            onClick={() => onOpenWebmail(`?account=${encodeURIComponent(account)}&folder=INBOX&uid=${e.uid}`)}>
                            <span className="dot" />
                            <span className="av">{(who[0] || '?').toUpperCase()}</span>
                            <span className="main">
                                <span className="s">{e.subject || tr('(no subject)')}</span>
                                <span className="m">{who} · {fmtTime(e.date || undefined)}</span>
                            </span>
                        </button>
                    )
                })}
            </div>
            {state !== 'loading' && (
                <div className="foot mail-foot">
                    <a className="wiki accent" onClick={() => onOpenWebmail('?compose=1')} style={{ cursor: 'pointer' }}>
                        <SquarePen size={14} /> {tr('New email')}
                    </a>
                    {state === 'ready' && (
                        <a className="wiki" onClick={() => onOpenWebmail()} style={{ cursor: 'pointer' }}>
                            <ExternalLink size={14} /> {tr('Open the webmail')}
                        </a>
                    )}
                </div>
            )}
        </div>
    )
}

// ── calendar / events ───────────────────────────────────────────────
export interface CalEvent {
    name: string
    subject?: string
    starts_on?: string
    ends_on?: string
    all_day?: 0 | 1
    color?: string
}

//// Neoffice — reminders are read from `Reminder` and not from the mirrored
//// events, for two reasons. It is a doctype of frappe itself, so it exists on
//// every instance (asking for our `Event.neo_reminder` custom field would make
//// get_list throw where it is absent, and take the whole panel down with it).
//// And its permissions are `if_owner`, so a user only ever reads their own — a
//// reminder is a private note.
export interface Reminder {
    name: string
    description?: string
    remind_at?: string
    reminder_doctype?: string
    reminder_docname?: string
}

function startOfToday(): string {
    const d = new Date()
    const p = (n: number) => String(n).padStart(2, '0')
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} 00:00:00`
}
function isToday(ts?: string): boolean {
    if (!ts) return false
    const d = new Date(ts.replace(' ', 'T'))
    return !isNaN(d.getTime()) && d.toDateString() === new Date().toDateString()
}

// Fetches upcoming Events once (from midnight today, ascending). Returns the
// list plus today's count for the date-widget badge. Polls on the same
// cadence as the other panels. Event is the stock Calendar doctype.
export function useDayEvents() {
    const [events, setEvents] = useState<CalEvent[]>([])
    const load = useCallback(() => {
        api<CalEvent[]>('frappe.client.get_list', {
            doctype: 'Event',
            filters: JSON.stringify([['starts_on', '>=', startOfToday()]]),
            fields: JSON.stringify(['name', 'subject', 'starts_on', 'ends_on', 'all_day', 'color']),
            order_by: 'starts_on asc',
            limit_page_length: '20',
        }).then(rows => setEvents(Array.isArray(rows) ? rows : []))
    }, [])
    useEffect(() => {
        load()
        const id = setInterval(load, POLL_MS)
        return () => clearInterval(id)
    }, [load])
    const todayCount = events.filter(e => isToday(e.starts_on)).length
    return { events, todayCount }
}

//// Neoffice — upcoming reminders of the current user. Failures are swallowed on
//// purpose: on a portal surface the caller has no Desk User role and get_list
//// refuses, which must leave the events panel intact rather than empty it.
export function useDayReminders() {
    const [reminders, setReminders] = useState<Reminder[]>([])
    const load = useCallback(() => {
        api<Reminder[]>('frappe.client.get_list', {
            doctype: 'Reminder',
            filters: JSON.stringify([['remind_at', '>=', startOfToday()], ['notified', '=', 0]]),
            fields: JSON.stringify(['name', 'description', 'remind_at', 'reminder_doctype', 'reminder_docname']),
            order_by: 'remind_at asc',
            limit_page_length: '20',
        })
            .then(rows => setReminders(Array.isArray(rows) ? rows : []))
            .catch(() => setReminders([]))
    }, [])
    useEffect(() => {
        load()
        const id = setInterval(load, POLL_MS)
        return () => clearInterval(id)
    }, [load])
    return { reminders }
}

function reminderWhen(r: Reminder, tr: (s: string) => string): string {
    if (!r.remind_at) return ''
    const d = new Date(r.remind_at.replace(' ', 'T'))
    if (isNaN(d.getTime())) return ''
    const day = isToday(r.remind_at)
        ? tr('Today')
        : d.toLocaleDateString([], { weekday: 'short', day: 'numeric', month: 'short' })
    const time = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    const on = r.reminder_docname ? ` · ${r.reminder_docname}` : ''
    return `${day} · ${time}${on}`
}

function eventWhen(e: CalEvent, tr: (s: string) => string): string {
    if (!e.starts_on) return ''
    const d = new Date(e.starts_on.replace(' ', 'T'))
    if (isNaN(d.getTime())) return ''
    const day = isToday(e.starts_on)
        ? tr('Today')
        : d.toLocaleDateString([], { weekday: 'short', day: 'numeric', month: 'short' })
    if (e.all_day) return day
    return `${day} · ${d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`
}

export function EventsPanel({ tr, events, reminders = [], onNavigate, onClose }: {
    tr: (s: string) => string
    events: CalEvent[]
    reminders?: Reminder[]
    onNavigate: (route: string) => void
    onClose: () => void
}) {
    const today = events.filter(e => isToday(e.starts_on))
    // today's events if any, otherwise the upcoming ones (agenda list view)
    const showingToday = today.length > 0
    const list = showingToday ? today : events
    return (
        <div className="nc-spa-panel">
            <div className="head">
                <span className="t">{showingToday ? tr('Today') : tr('Upcoming events')}</span>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {!list.length && <div className="empty">{tr('No upcoming events.')}</div>}
                {list.map(e => (
                    <button key={e.name} className="row" onClick={() => onNavigate(`/app/event/${encodeURIComponent(e.name)}`)}>
                        <span className="av" style={e.color ? { background: e.color + '22', color: e.color } : undefined}>
                            <CalendarDays size={15} strokeWidth={1.9} />
                        </span>
                        <span className="main">
                            <span className="s">{e.subject || tr('(untitled)')}</span>
                            <span className="m">{eventWhen(e, tr)}</span>
                        </span>
                    </button>
                ))}
                {/* //// Neoffice — reminders get their OWN section, under the events.
                    A "Remind Me" reminder is nearly always set for a later day, and
                    this panel shows only TODAY's events as soon as one exists — so a
                    reminder folded into that list would be invisible exactly when it
                    matters. Clicking one opens the DOCUMENT it was set from, which is
                    what you wanted to come back to; the reminder itself has nothing
                    else to show. */}
                {reminders.length > 0 && (
                    <>
                        <div className="sect">{tr('Reminders')}</div>
                        {reminders.map(r => (
                            <button key={r.name} className="row"
                                onClick={() => onNavigate(
                                    r.reminder_doctype && r.reminder_docname
                                        ? `/app/${encodeURIComponent(r.reminder_doctype.toLowerCase().replace(/ /g, '-'))}/${encodeURIComponent(r.reminder_docname)}`
                                        : '/app/reminder'
                                )}>
                                <span className="av"><AlarmClock size={15} strokeWidth={1.9} /></span>
                                <span className="main">
                                    <span className="s">{r.description || tr('Reminder')}</span>
                                    <span className="m">{reminderWhen(r, tr)}</span>
                                </span>
                            </button>
                        ))}
                    </>
                )}
            </div>
            <div className="foot">
                <a className="wiki" onClick={() => onNavigate('/app/event/view/calendar')} style={{ cursor: 'pointer' }}>
                    <CalendarClock size={14} /> {tr('Open the calendar')}
                </a>
            </div>
        </div>
    )
}

// ── help (shared wiki) ──────────────────────────────────────────────
interface WikiDoc { name: string; title?: string; url?: string; route?: string }

export function HelpPanel({ tr, wikiUrl, onClose }: { tr: (s: string) => string; wikiUrl: string; onClose: () => void }) {
    const [results, setResults] = useState<WikiDoc[] | null>(null)
    // //// Neoffice — remote assistance: the panel gives a place, the theme's client draws what goes in it (asking the
    // Neoservice team for help), and draws nothing where assistance is not set up. ////
    const assistSlot = useRef<HTMLDivElement>(null)
    useEffect(() => {
        let alive = true
        let remove: (() => void) | undefined
        void loadAssist().then((assist) => {
            if (alive && assist && assistSlot.current) remove = assist.render_help_entry(assistSlot.current)
        })
        return () => { alive = false; remove?.() }
    }, [])
    const timer = useRef<ReturnType<typeof setTimeout>>()
    const search = useCallback((q: string) => {
        clearTimeout(timer.current)
        if (!q || q.length < 2) { setResults(null); return }
        timer.current = setTimeout(async () => {
            const res = await api<WikiDoc[]>('neoffice_theme.api.search_docs', { query: q, limit: '6' })
            setResults(res || [])
        }, 300)
    }, [])
    return (
        <div className="nc-spa-panel">
            <div className="head">
                <span className="t">{tr('Help & Training')}</span>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {/* //// Neoffice — remote assistance (see above) //// */}
                <div className="nc-assist-slot" ref={assistSlot} />
                <div className="searchbox">
                    <Search size={15} strokeWidth={1.8} />
                    <input placeholder={tr('Search the wiki...')} onChange={e => search(e.target.value)} autoFocus />
                </div>
                {results !== null && !results.length && <div className="empty">{tr('No wiki page found')}</div>}
                {(results || []).map(r => (
                    <a key={r.name} className="row" href={r.url || wikiUrl} target="_blank" rel="noopener">
                        <span className="main"><span className="s link">{r.title || r.name}</span></span>
                        <ExternalLink size={13} className="arr" />
                    </a>
                ))}
            </div>
            <div className="foot">
                <a className="wiki" href={wikiUrl} target="_blank" rel="noopener">
                    <ExternalLink size={14} /> {tr('Open the Neoffice wiki')}
                </a>
            </div>
        </div>
    )
}

// ── favorites (user-pinned routes, theme-backed) ────────────────────
export interface CockpitFavorite {
    name: string
    label: string
    route: string
    fav_type?: string
    icon?: string
}

export async function fetchFavorites(): Promise<CockpitFavorite[]> {
    return (await api<CockpitFavorite[]>('neoffice_theme.cockpit_favorites.get_favorites')) || []
}

export function FavoritesPanel({ tr, favorites, onNavigate, onRemove, onClose }: {
    tr: (s: string) => string
    favorites: CockpitFavorite[]
    onNavigate: (route: string) => void
    onRemove: (fav: CockpitFavorite) => void
    onClose: () => void
}) {
    const [q, setQ] = useState('')
    const TYPE_HINT: Record<string, string> = {
        Workspace: tr('Workspace'), List: tr('List'), Form: tr('Document'),
        Report: tr('Report'), Page: tr('Page'),
    }
    const list = q
        ? favorites.filter(f => (f.label + ' ' + (f.fav_type || '')).toLowerCase().includes(q.toLowerCase()))
        : favorites
    return (
        <div className="nc-spa-panel">
            <div className="head">
                <span className="t">{tr('Favorites')}</span>
                <button className="x" onClick={onClose}>&times;</button>
            </div>
            <div className="body">
                {favorites.length > 6 && (
                    <div className="searchbox">
                        <Search size={15} strokeWidth={1.8} />
                        <input placeholder={tr('Filter…')} value={q} onChange={e => setQ(e.target.value)} autoFocus />
                    </div>
                )}
                {!list.length && <div className="empty">{tr('No favorites yet — star a page to pin it here.')}</div>}
                {list.map(f => (
                    <div key={f.name} className="row fav-row">
                        <button className="main fav-go" onClick={() => onNavigate(f.route)}>
                            <span className="s">{f.label}</span>
                            <span className="m">{TYPE_HINT[f.fav_type || ''] || f.fav_type || ''}</span>
                        </button>
                        <button className="fav-x" title={tr('Remove')} onClick={() => onRemove(f)}>&times;</button>
                    </div>
                ))}
            </div>
        </div>
    )
}
